const DB='modu-ai-store-media-v1';
const memory=new Map();const preview=typeof location!=='undefined'&&new URLSearchParams(location.search).get('preview')==='1';
async function database(){return new Promise((resolve,reject)=>{const q=indexedDB.open(DB,1);q.onupgradeneeded=()=>q.result.createObjectStore('files',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export async function saveFiles(files,kind){if(!files.length||files.length>3)throw new Error('uploadLimit');const allowedImages=['image/jpeg','image/png','image/webp','image/heic','image/heif'];for(const f of files){const image=allowedImages.includes(f.type),video=kind==='venue'&&['video/mp4','video/webm','video/quicktime'].includes(f.type);if((!image&&!video)||f.size>(video?25:5)*1024*1024)throw new Error('uploadLimit');}const records=files.map(file=>({id:crypto.randomUUID(),name:file.name,type:file.type,size:file.size,blob:file,at:new Date().toISOString()}));if(preview){for(const r of records)memory.set(r.id,r);}else{const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');for(const r of records)tx.objectStore('files').put(r);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});db.close();}return records.map(({blob,...r})=>r);}
export async function mediaUrl(id){let record;if(preview)record=memory.get(id);else{const db=await database();record=await new Promise((resolve,reject)=>{const q=db.transaction('files').objectStore('files').get(id);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});db.close();}return record?.blob?URL.createObjectURL(record.blob):null;}
